import{_ as a,c as r,o as n,j as o,Y as i,t as s}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"nice | x-cmd man (man1) | run a program with modified scheduling priority","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | nice - run a program with modified scheduling priority","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nice | x-cmd man (man1) | run a program with modified scheduling priority"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | nice - run a program with modified scheduling priority"}]]},"headers":[],"params":{"isMan":true,"man":"nice","category":"man1","desc":"run a program with modified scheduling priority"},"relativePath":"man1/nice.md","filePath":"man1/[man].md"}'),d={name:"man1/nice.md"},l={class:"visually-hidden"};function h(t,e,c,p,u,m){return n(),r("div",null,[o("h1",l,s(t.$params.man),1),e[0]||(e[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nice - run a program with modified scheduling priority</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>nice</strong> [<em>OPTION</em>] [*COMMAND *[<em>ARG</em>]...]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Run COMMAND with an adjusted niceness, which affects process scheduling. With no COMMAND, print the current niceness. Niceness values range from <strong>-20</strong> (most favorable to the process) to 19 (least favorable to the process).</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-n</strong>, <strong>--adjustment</strong>=<em>N</em></dt><dd>add integer N to the niceness (default 10)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>NOTE: your shell may have its own version of nice, which usually supersedes the version described here. Please refer to your shell&#39;s documentation for details about the options it supports.</p><h3 id="exit-status" tabindex="-1">Exit status: <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status:&quot;">​</a></h3><dl><dt>125</dt><dd>if the nice command itself fails</dd><dt>126</dt><dd>if COMMAND is found but cannot be invoked</dd><dt>127</dt><dd>if COMMAND cannot be found</dd><dt>-</dt><dd>the exit status of COMMAND otherwise</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nice</strong>(2), <strong>renice</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/nice%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/nice\\</a>&gt; <br> or available locally via: info &#39;(coreutils) nice invocation&#39;</p>',20))])}const b=a(d,[["render",h]]);export{f as __pageData,b as default};
